<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Tasks</title><?= view('partials/styles') ?></head>
<body><div class="app-shell"><?= view('partials/nav', ['active' => 'tasks']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Workspace</p><h1>Tasks for today</h1><p class="subtitle">View upcoming work and manage your daily operations.</p></div><div class="profile"><div class="avatar"><?= session()->get('isLoggedIn') ? esc(strtoupper(substr(session()->get('full_name'), 0, 2))) : 'GU' ?></div><?= session()->get('isLoggedIn') ? esc(session()->get('full_name')) : 'Guest' ?></div></header>
<?php if ($message = session()->getFlashdata('success')): ?><p class="badge" style="margin-bottom:18px"><?= esc($message) ?></p><?php endif; ?><?php if ($message = session()->getFlashdata('error')): ?><p class="badge" style="background:#ffe8e8;color:#b42318;margin-bottom:18px"><?= esc($message) ?></p><?php endif; ?>
<section class="panel"><div class="panel-heading"><h2>Active tasks</h2><div><span style="margin-right:16px"><?= count($tasks) ?> tasks</span><?php if (session()->get('isLoggedIn')): ?><a class="button" href="<?= base_url('tasks/new') ?>">+ New task</a><?php else: ?><a class="button" href="<?= base_url('login') ?>">Log in to manage</a><?php endif; ?></div></div><div class="table-wrap"><table><thead><tr><th>Task</th><th>Due date</th><th>Description</th><th>Actions</th></tr></thead><tbody><?php if (! $tasks): ?><tr><td colspan="4">No active tasks found.</td></tr><?php endif; ?><?php foreach ($tasks as $task): ?><tr><td><div class="person"><span class="person-avatar">✓</span><?= esc($task['title']) ?></div></td><td><?= esc(date('M d, Y', strtotime($task['task_date']))) ?></td><td><?= esc($task['description'] ?? '') ?></td><td><?php if (session()->get('isLoggedIn')): ?><a href="<?= base_url('tasks/edit/' . $task['id']) ?>">Edit</a> <form method="post" action="<?= base_url('tasks/delete/' . $task['id']) ?>" style="display:inline;margin-left:8px"><button type="submit" style="border:0;background:none;color:#b42318;cursor:pointer;padding:0" onclick="return confirm('Archive this task?')">Archive</button></form><?php else: ?><span style="color:var(--muted)">Login required</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></main></div></body></html>
